def get_positive_integer(prompt):
    """Prompts the user to enter a positive integer and validates the input."""
    while True:
        try:
            num = int(input(prompt))
            if num > 0:
                return num
            else:
                print("Please enter a positive integer.")
        except ValueError:
            print("That's not a valid integer. Please try again.")

def calculate_total_revenue(num_items, item_prices):
    """Calculates the total revenue based on the number of items sold and their prices."""
    total_revenue = 0
    for i, price in enumerate(item_prices):
        if i < len(item_prices) - 1:
            print(f"Sold {num_items - i} more items at ${price}.")
        else:
            print(f"Sold the last {num_items - i} items at ${price}.")
        total_revenue += price * (num_items - i)
    print(f"Total revenue: ${total_revenue}")

# Get user input
num_items = get_positive_integer("Enter the number of items sold: ")
item_prices = [float(price) for price in input("Enter the prices of the items separated by spaces: ").split()]

# Calculate and display total revenue
calculate_total_revenue(num_items, item_prices)
```
